create role anon nologin;
create role authenticated nologin;
create role service_role nologin bypassrls;
create schema auth;
create schema private;
create schema extensions;
grant usage on schema public,auth,private to anon,authenticated,service_role;
alter default privileges in schema public,private grant all on tables to anon,authenticated,service_role;
alter default privileges in schema public,private grant execute on functions to anon,authenticated,service_role;
create function auth.uid() returns uuid language sql stable as $$ select nullif(current_setting('request.jwt.claims',true)::jsonb->>'sub','')::uuid $$;
create function auth.jwt() returns jsonb language sql stable as $$ select coalesce(nullif(current_setting('request.jwt.claims',true),''),'{}')::jsonb $$;
create table auth.users(id uuid primary key,banned_until timestamptz,updated_at timestamptz);
create table public.profiles(id uuid primary key references auth.users(id),app_role text,account_status text default 'active',login_name text,credentials_valid_after timestamptz default '2020-01-01');
create table public.internal_org_people(id uuid primary key,node_kind text default 'person',company_key text default 'mam',full_name text,position_title text default 'Synthetic role',auth_user_id uuid unique references auth.users(id),parent_id uuid references public.internal_org_people(id),is_active boolean default true);
create table private.employee_directory_details(person_id uuid primary key references public.internal_org_people(id),team_name text);
create table private.subscription_management_grants(person_id uuid,employee_delegation_confirmed boolean);
create table private.subscription_credential_access_grants(person_id uuid,auth_user_id uuid,employee_delegation_confirmed boolean);
create table private.employee_roster_external_manager_roots(org_unit_id uuid,manager_label text);
create table private.confirmed_test_identity_purges(auth_user_id uuid,phase text,retired_identifiers uuid[]);
insert into auth.users(id) select ('a1000000-0000-4000-8000-'||lpad(i::text,12,'0'))::uuid from generate_series(1,9) i;
insert into public.profiles(id,app_role,login_name) select id,case right(id::text,1) when '2' then 'manager' when '3' then 'manager' when '4' then 'admin' when '5' then 'system_admin' when '6' then 'account' when '8' then 'manager' when '9' then 'manager' else 'employee' end,'synthetic-'||right(id::text,1) from auth.users;
insert into public.internal_org_people(id,auth_user_id,full_name,company_key) select ('b1000000-0000-4000-8000-'||right(id::text,12))::uuid,id,'Synthetic person '||right(id::text,1),case right(id::text,1) when '7' then 'equipsy' when '8' then 'equipsy' else 'mam' end from auth.users where right(id::text,1)<>'5';
update public.internal_org_people set parent_id='b1000000-0000-4000-8000-000000000002' where right(id::text,1) in ('1','6');
update public.internal_org_people set parent_id='b1000000-0000-4000-8000-000000000009' where right(id::text,1)='2';
update public.internal_org_people set parent_id='b1000000-0000-4000-8000-000000000008' where right(id::text,1)='7';
revoke all on all tables in schema public,private,auth from public,anon,authenticated,service_role;
